import { LOGO_CORE, LOGO_SPIRAL, LOGO_STROKE, LOGO_TAIL, LOGO_VIEWBOX } from "@/lib/logo-geometry";

/**
 * The Threadcore mark: a ball of thread (solid core, one winding thread, a loose end).
 * Geometry is generated by scripts/generate-logo.mjs.
 */
export function LogoMark({
  className,
  tone = "dark",
}: {
  className?: string;
  /** "dark" = for light backgrounds, "light" = for dark backgrounds. */
  tone?: "dark" | "light";
}) {
  const core = tone === "dark" ? "var(--ink)" : "#ffffff";
  const thread = tone === "dark" ? "var(--brand-accent)" : "#ff6a47";
  return (
    <svg viewBox={LOGO_VIEWBOX} aria-hidden="true" className={className}>
      <g fill="none" stroke={thread} strokeWidth={LOGO_STROKE} strokeLinecap="round" strokeLinejoin="round">
        <path d={LOGO_SPIRAL} />
        <path d={LOGO_TAIL} />
      </g>
      {/* The core sits on top so the thread appears to emerge from beneath it. */}
      <circle cx={LOGO_CORE.cx} cy={LOGO_CORE.cy} r={LOGO_CORE.r} fill={core} />
    </svg>
  );
}
